"use client";
import {useCallback,useEffect,useState} from "react";import {usePathname} from "next/navigation";import {Plus,Search,RefreshCw,Filter,Download,Pencil,Trash2,Eye,X} from "lucide-react";import {useSession} from "@/components/auth/session-provider";
type Vendor={id:number;name:string;email:string|null;pan:string|null;gstin:string|null;industry:string|null;mobile:string|null;state:string|null;status:string;gstnType:string};
const empty={name:"",industry:"",email:"",website:"",landline:"",mobile:"",addressLine1:"",addressLine2:"",gstnType:"REGISTERED_REGULAR",gstin:"",pan:"",currency:"INR",country:"India",state:"Tamil Nadu",pinCode:"",tcsEnabled:false,tcsRate:"0",openingDate:"",openingType:"CREDIT",openingAmount:"0",portalEnabled:false};
export function VendorsClient(){const path=usePathname();const base=path.startsWith("/superadmin")?"/superadmin":"/dashboard";const {user}=useSession();const readonly=user?.role==="SUPERADMIN";const [rows,setRows]=useState<Vendor[]>([]);const [search,setSearch]=useState("");const [status,setStatus]=useState("all");const [state,setState]=useState("all");const [page,setPage]=useState(1);const [total,setTotal]=useState(0);const [form,setForm]=useState<any>(empty);const [editing,setEditing]=useState<number|null>(null);const [show,setShow]=useState(false);const [busy,setBusy]=useState(false);const [error,setError]=useState("");
const load=useCallback(async()=>{const q=new URLSearchParams({search,status,state,page:String(page),pageSize:"15"});const r=await fetch(`/api/vendors?${q}`);const j=await r.json();if(r.ok){setRows(j.data);setTotal(j.total)}else setError(j.error||"Unable to load vendors")},[search,status,state,page]);useEffect(()=>{load()},[load]);
const start=(v?:Vendor)=>{setEditing(v?.id??null);setForm(v?{...empty,...v,gstin:v.gstin||"",email:v.email||"",pan:v.pan||""}:{...empty});setError("");setShow(true)};
const save=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);setError("");try{const r=await fetch(editing?`/api/vendors/${editing}`:"/api/vendors",{method:editing?"PATCH":"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(form)});const j=await r.json();if(!r.ok)throw new Error(j.error);setShow(false);await load()}catch(e){setError(e instanceof Error?e.message:"Save failed")}finally{setBusy(false)}};
const remove=async(v:Vendor)=>{if(!confirm(`Delete vendor ${v.name}?`))return;const r=await fetch(`/api/vendors/${v.id}`,{method:"DELETE"});const j=await r.json();if(!r.ok)alert(j.error);else load()};
const exportCsv=()=>{const header=["Vendor Name","Email","PAN","GSTIN","State","Mobile"];const lines=rows.map(v=>[v.name,v.email,v.pan,v.gstin,v.state,v.mobile].map(x=>`"${String(x||"").replaceAll('"','""')}"`).join(","));const blob=new Blob([[header.join(","),...lines].join("\n")],{type:"text/csv"});const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="vendors.csv";a.click();URL.revokeObjectURL(a.href)};
return <div className="space-y-5"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="text-sm text-muted-foreground">Masters / Vendors</p><h1 className="text-2xl font-bold">Vendor Details (Purchasing From)</h1><p className="text-sm text-muted-foreground">Manage companies and suppliers from whom your business purchases goods or services.</p></div>{!readonly&&<button onClick={()=>start()} className="inline-flex items-center gap-2 rounded-lg bg-primary px-4 py-2 text-sm font-semibold text-primary-foreground"><Plus size={16}/> New Vendor</button>}</div>
<div className="rounded-xl border bg-card p-4 shadow-sm space-y-4"><div className="flex flex-wrap items-center justify-between gap-2"><div className="flex gap-2"><button onClick={load} className="rounded-lg border px-3 py-2 text-sm inline-flex gap-2 items-center"><RefreshCw size={15}/> Refresh</button><button onClick={exportCsv} className="rounded-lg border px-3 py-2 text-sm inline-flex gap-2 items-center"><Download size={15}/> Export CSV</button></div><div className="flex flex-wrap gap-2"><div className="relative"><Search className="absolute left-3 top-2.5 size-4 text-muted-foreground"/><input value={search} onChange={e=>{setPage(1);setSearch(e.target.value)}} placeholder="Search vendor, email, PAN, GSTIN" className="h-9 w-64 rounded-lg border bg-background pl-9 pr-3 text-sm"/></div><select value={status} onChange={e=>setStatus(e.target.value)} className="h-9 rounded-lg border bg-background px-3 text-sm"><option value="all">All Status</option><option value="active">Active</option><option value="inactive">Inactive</option></select><select value={state} onChange={e=>setState(e.target.value)} className="h-9 rounded-lg border bg-background px-3 text-sm"><option value="all">All States</option>{[...new Set(rows.map(v=>v.state).filter(Boolean))].map(s=><option key={s} value={s!}>{s}</option>)}</select></div></div>
<div className="overflow-x-auto"><table className="w-full min-w-[850px] text-left text-sm"><thead className="bg-primary text-primary-foreground"><tr>{["Vendor Name","Email","PAN No","GSTIN No","State","Status","Actions"].map(x=><th key={x} className="px-3 py-3 font-semibold">{x}</th>)}</tr></thead><tbody>{rows.map(v=><tr key={v.id} className="border-b last:border-0 hover:bg-muted/40"><td className="px-3 py-3 font-medium">{v.name}</td><td className="px-3 py-3">{v.email||"—"}</td><td className="px-3 py-3">{v.pan||"—"}</td><td className="px-3 py-3">{v.gstin||"—"}</td><td className="px-3 py-3">{v.state||"—"}</td><td className="px-3 py-3"><span className="rounded-full bg-emerald-100 px-2 py-1 text-xs text-emerald-700">{v.status}</span></td><td className="px-3 py-3"><div className="flex gap-2">{!readonly&&<button title="Edit" onClick={()=>start(v)} className="rounded p-1.5 hover:bg-muted"><Pencil size={15}/></button>}{!readonly&&<button title="Delete" onClick={()=>remove(v)} className="rounded p-1.5 text-destructive hover:bg-muted"><Trash2 size={15}/></button>}</div></td></tr>)}{!rows.length&&<tr><td colSpan={7} className="p-10 text-center text-muted-foreground">No vendors found. Add your first vendor.</td></tr>}</tbody></table></div><div className="flex items-center justify-between text-sm text-muted-foreground"><span>Showing {rows.length} of {total} vendors</span><div className="flex gap-2"><button disabled={page<=1} onClick={()=>setPage(p=>p-1)} className="rounded border px-3 py-1 disabled:opacity-40">Previous</button><span className="px-2 py-1">{page}</span><button disabled={page*15>=total} onClick={()=>setPage(p=>p+1)} className="rounded border px-3 py-1 disabled:opacity-40">Next</button></div></div></div>
{show&&<div className="fixed inset-0 z-50 overflow-y-auto bg-black/40 p-4"><div className="mx-auto my-6 max-w-5xl rounded-2xl bg-card shadow-2xl"><div className="flex items-center justify-between border-b p-5"><div><h2 className="text-xl font-bold">{editing?"Edit Vendor":"New Vendor"}</h2><p className="text-sm text-muted-foreground">Enter vendor contact, GST and opening balance details.</p></div><button onClick={()=>setShow(false)}><X/></button></div><form onSubmit={save} className="space-y-5 p-5"><Section title="Basic Information"><Field label="Vendor Name *" value={form.name} onChange={v=>setForm({...form,name:v})}/><Field label="Industry" value={form.industry} onChange={v=>setForm({...form,industry:v})}/><Field label="Official Email ID" value={form.email} onChange={v=>setForm({...form,email:v})} type="email"/><Field label="Website" value={form.website} onChange={v=>setForm({...form,website:v})}/><Field label="Landline Phone" value={form.landline} onChange={v=>setForm({...form,landline:v})}/><Field label="Mobile" value={form.mobile} onChange={v=>setForm({...form,mobile:v})}/><Field label="Address Line 1" value={form.addressLine1} onChange={v=>setForm({...form,addressLine1:v})}/><Field label="Address Line 2" value={form.addressLine2} onChange={v=>setForm({...form,addressLine2:v})}/></Section><Section title="GST & Tax Information"><SelectField label="GSTN Type" value={form.gstnType} onChange={v=>setForm({...form,gstnType:v})} options={[["REGISTERED_REGULAR","GST Registered - Regular"],["COMPOSITION","Composition"],["UNREGISTERED","Unregistered"],["CONSUMER","Consumer"]]}/><Field label="GSTN No" value={form.gstin} onChange={v=>setForm({...form,gstin:v.toUpperCase()})}/><Field label="PAN" value={form.pan} onChange={v=>setForm({...form,pan:v.toUpperCase()})}/><SelectField label="Currency" value={form.currency} onChange={v=>setForm({...form,currency:v})} options={[["INR","INR"],["USD","USD"],["EUR","EUR"]]}/><label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={form.tcsEnabled} onChange={e=>setForm({...form,tcsEnabled:e.target.checked})}/> Enable TCS</label><Field label="TCS %" type="number" value={form.tcsRate} onChange={v=>setForm({...form,tcsRate:v})}/></Section><Section title="Location"><Field label="Country" value={form.country} onChange={v=>setForm({...form,country:v})}/><Field label="State" value={form.state} onChange={v=>setForm({...form,state:v})}/><Field label="PIN Code" value={form.pinCode} onChange={v=>setForm({...form,pinCode:v})}/></Section><Section title="Opening Balance"><Field label="Date (as On)" type="date" value={form.openingDate} onChange={v=>setForm({...form,openingDate:v})}/><SelectField label="Balance Type" value={form.openingType} onChange={v=>setForm({...form,openingType:v})} options={[["CREDIT","Credit"],["DEBIT","Debit"]]}/><Field label="Amount" type="number" value={form.openingAmount} onChange={v=>setForm({...form,openingAmount:v})}/></Section><Section title="Vendor Portal"><label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={form.portalEnabled} onChange={e=>setForm({...form,portalEnabled:e.target.checked})}/> Enable Vendor Portal</label><p className="text-xs text-muted-foreground">Enabling this flag does not create login credentials; portal account provisioning must be configured separately.</p></Section>{error&&<p className="rounded-lg bg-destructive/10 p-3 text-sm text-destructive">{error}</p>}<div className="flex justify-end gap-2"><button type="button" onClick={()=>setShow(false)} className="rounded-lg border px-4 py-2">Back</button><button disabled={busy} className="rounded-lg bg-primary px-5 py-2 text-primary-foreground">{busy?"Saving…":"Save Vendor"}</button></div></form></div></div>}</div>}
function Section({title,children}:{title:string;children:React.ReactNode}){return <section className="rounded-xl border p-4"><h3 className="mb-4 font-semibold text-primary">{title}</h3><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">{children}</div></section>}
function Field({label,value,onChange,type="text"}:{label:string;value:string;onChange:(v:string)=>void;type?:string}){return <label className="block space-y-1 text-sm"><span className="text-muted-foreground">{label}</span><input type={type} value={value??""} onChange={e=>onChange(e.target.value)} className="h-10 w-full rounded-lg border bg-background px-3 outline-none focus:ring-2 focus:ring-primary/20"/></label>}
function SelectField({label,value,onChange,options}:{label:string;value:string;onChange:(v:string)=>void;options:string[][]}){return <label className="block space-y-1 text-sm"><span className="text-muted-foreground">{label}</span><select value={value} onChange={e=>onChange(e.target.value)} className="h-10 w-full rounded-lg border bg-background px-3">{options.map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></label>}
